const I18N_RULES=[
  [/^· dernière passe à (.+)$/,m=>'· last run at '+m[1]],
  [/^Édité le (.+?)\. (\d+) valeur\(s\) forcée\(s\) par l'analyste, signalées par \*\. Rapport d'aide à la décision, ne constitue pas un conseil en investissement\.$/,m=>`Edited on ${m[1]}. ${m[2]} value(s) forced by the analyst, marked with *. Decision-support report, not investment advice.`],
  [/^(\d+) séances?$/,m=>m[1]+' sessions'],
  [/^(.+) · (\d+) dernières séances$/,m=>`${i18nT(m[1])} · last ${m[2]} sessions`],
  [/^([+\-−]?[\d\s,.]+ %) sur la séance$/,m=>m[1]+' on the session'],
  [/^Sans dossier · (\d+) versions?$/,m=>`No folder · ${m[1]} version${m[1]>1?'s':''}`],
  [/^(\d+) trades? enregistrés?$/,m=>`${m[1]} trade${m[1]>1?'s':''} recorded`],
  [/^(\d+) lignes?$/,m=>`${m[1]} position${m[1]>1?'s':''}`],
  [/^(\d+) importés de MT5$/,m=>`${m[1]} imported from MT5`],
  [/^(\d+) positives? sur (\d+)$/,m=>`${m[1]} positive out of ${m[2]}`],
  [/^(\d+) dossiers? retenus? sur (\d+)$/,m=>`${m[1]} file(s) selected out of ${m[2]}`],
  [/^Filtre (\d) : (.+)$/,m=>`Filter ${m[1]}: ${i18nT(m[2])}`],
  [/^(\d+|[IVX]+)\. (.+)$/,m=>{const t=i18nT(m[2]);return t!==m[2]?`${m[1]}. ${t}`:undefined;}],
  [/^([^:]{3,60}?) : (.+)$/,m=>{const l=I18N_EN[m[1].trim()];if(l===undefined)return undefined;const r=i18nT(m[2]);return`${l.replace(/:$/,'')}: ${r}`;}],
  [/^Modifier (.+)$/,m=>'Edit '+i18nT(m[1])],
  [/^Mise à jour : (.+) à (\d{1,2}:\d{2})$/,m=>`Updated: ${m[1]} at ${m[2]}`],
  [/^dernière passe à (\d{1,2}:\d{2})$/,m=>`last run at ${m[1]}`],
  [/^Calculé à (.+)$/,m=>'Calculated at '+m[1]],
  [/^Bonjour (.+?) ?!?$/,m=>'Hello '+m[1]+(/!$/.test(m[0])?'!':'')],
  [/^(\d+) demande\(s\) en attente de Claude$/,m=>`${m[1]} request(s) waiting for Claude`],
  [/^(\d+) séances? sur (\d+)$/,m=>`${m[1]} sessions out of ${m[2]}`],
  [/^(\d+) valeurs? forcées?$/,m=>`${m[1]} forced value${m[1]>1?'s':''}`],
  [/^(\d+) projets? · (\d+) versions?$/,m=>`${m[1]} project${m[1]>1?'s':''} · ${m[2]} version${m[2]>1?'s':''}`],
  [/^(\d+) titres? couverts?$/,m=>`${m[1]} stocks covered`],
  [/^séance du (.+)$/,m=>'session of '+m[1]],
  [/^Connecté : (.+)$/,m=>'Signed in: '+m[1]],
  [/^Mise à jour (\d+)\/(\d+)$/,m=>`Update ${m[1]}/${m[2]}`],
  [/^Sources publiques (\d+)\/(\d+)$/,m=>`Public sources ${m[1]}/${m[2]}`],
  [/^Claude : (.+?)\/(\d+) demandes traitées$/,m=>`Claude: ${m[1]}/${m[2]} requests processed`],
  [/^passage automatique vers (.+)$/,m=>'automatic run around '+m[1]],
  [/^Ouvert : (.+)$/,m=>'Opened: '+m[1]],
  [/^Renommé : (.+)$/,m=>'Renamed: '+m[1]],
  [/^(.+) : décision (négative|positive)$/,m=>`${m[1]}: ${m[2]==='négative'?'negative':'positive'} decision`],
  [/^Toutes les matières premières (.+)$/,m=>'All commodities '+m[1]],
];
const I18N_LANG=()=>{try{return localStorage.getItem('fomo.lang')==='en'?'en':'fr';}catch(e){return'fr';}};
function i18nT(s){if(!s)return s;const k=s.trim();if(!k)return s;let t=I18N_EN[k];
  if(t===undefined){for(const[re,fn]of I18N_RULES){const m=k.match(re);if(m){const v=fn(m);if(v!==undefined){t=v;break;}}}}
  if(t===undefined&&k.includes(' · ')){const parts=k.split(' · '),tr=parts.map(p=>I18N_EN[p.trim()]);if(tr.some(x=>x!==undefined))t=parts.map((p,i)=>tr[i]!==undefined?tr[i]:p).join(' · ');}
  /* fragments fréquents dans les libellés variables */
  if(t!==undefined)t=t.replace(/ du capital\b/g,' of capital').replace(/ saisis? au journal/g,' entered in the journal').replace(/ par trade\b/g,' per trade').replace(/ sur (\d+) semaines/g,' over $1 weeks').replace(/ dans la zone\b/g,' in the area');
  if(t===undefined)return s;const lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0];return lead+t+trail;}
const I18N_NODES=new Set(),I18N_ORIG=new WeakMap(),I18N_ATTRS=['placeholder','title','aria-label'];
const i18nSkip=el=>!el||el.closest('script,style,textarea,#fdChatLog,[data-noi18n],.lwleg');
function i18nApply(root){const en=I18N_LANG()==='en';root=root||document.body;if(!root)return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;const todo=[];
  while(n=w.nextNode()){if(!/[A-Za-zÀ-ÿ]/.test(n.nodeValue)||i18nSkip(n.parentElement))continue;todo.push(n);}
  for(const t of todo){if(en){const o=I18N_ORIG.has(t)?I18N_ORIG.get(t):t.nodeValue,tr=i18nT(o);if(tr!==o){if(!I18N_ORIG.has(t))I18N_ORIG.set(t,o);I18N_NODES.add(t);if(t.nodeValue!==tr)t.nodeValue=tr;}}
    else if(I18N_ORIG.has(t)){const o=I18N_ORIG.get(t);if(t.nodeValue!==o)t.nodeValue=o;}}
  const els=root.querySelectorAll?root.querySelectorAll('[placeholder],[title],[aria-label]'):[];
  els.forEach(el=>{if(i18nSkip(el))return;I18N_ATTRS.forEach(a=>{if(!el.hasAttribute(a))return;const key='data-i18n-'+a,orig=el.getAttribute(key)??el.getAttribute(a);
    if(en){const tr=i18nT(orig);if(tr!==orig){el.setAttribute(key,orig);if(el.getAttribute(a)!==tr)el.setAttribute(a,tr);}}
    else if(el.hasAttribute(key)){el.setAttribute(a,el.getAttribute(key));el.removeAttribute(key);}});});
  document.documentElement.lang=en?'en':'fr';}
/* nouveaux contenus (rendus, toasts, réponses) : traduits dès qu'ils apparaissent */
let I18N_OBS=null,I18N_PEND=false;
function i18nWatch(){if(I18N_OBS)return;I18N_OBS=new MutationObserver(()=>{if(I18N_PEND||I18N_LANG()!=='en')return;I18N_PEND=true;
  requestAnimationFrame(()=>{I18N_PEND=false;I18N_OBS.disconnect();try{i18nApply();}finally{I18N_OBS.observe(document.body,{childList:true,subtree:true,characterData:true});}});});
  I18N_OBS.observe(document.body,{childList:true,subtree:true,characterData:true});}
function i18nSet(l){try{localStorage.setItem('fomo.lang',l);}catch(e){}if(typeof renderAll==='function')renderAll();
  if(I18N_OBS)I18N_OBS.disconnect();i18nApply();if(I18N_OBS)I18N_OBS.observe(document.body,{childList:true,subtree:true,characterData:true});
  toast(l==='en'?'Language: English':'Langue : français');}
/* sélecteur dans Paramètres */
function i18nCard(){return`<div class="card s12" id="i18nCard" data-noi18n><h2><span>${I18N_LANG()==='en'?'Language':'Langue'} <span class="meta">${I18N_LANG()==='en'?'interface display, applied immediately':"affichage de l'interface, appliqué immédiatement"}</span></span></h2>
  <div class="row" role="radiogroup" aria-label="Langue / Language"><button class="btn sm${I18N_LANG()==='fr'?' pri':''}" data-lang="fr" role="radio" aria-checked="${I18N_LANG()==='fr'}">Français</button><button class="btn sm${I18N_LANG()==='en'?' pri':''}" data-lang="en" role="radio" aria-checked="${I18N_LANG()==='en'}">English</button></div>
  ${I18N_LANG()==='en'?'<p class="note">Figures, sources and quoted excerpts stay in their original language. The assistant answers in English.</p>':"<p class=\"note\">Les chiffres, les sources et les extraits cités restent dans leur langue d'origine.</p>"}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-lang]');if(!b)return;i18nSet(b.dataset.lang);});
if(typeof renderAll==='function'){const _ri=renderAll;renderAll=function(){const r=_ri.apply(this,arguments);
  try{if(ui.tab==='set'){const P=document.getElementById('p-set');if(P&&!P.querySelector('#i18nCard')){const g=P.querySelector('.grid')||P;g.insertAdjacentHTML('afterbegin',i18nCard());}}}catch(e){}
  try{if(I18N_LANG()==='en'){if(I18N_OBS)I18N_OBS.disconnect();i18nApply();if(I18N_OBS)I18N_OBS.observe(document.body,{childList:true,subtree:true,characterData:true});}}catch(e){}return r;};}
setTimeout(()=>{i18nWatch();if(I18N_LANG()==='en')i18nApply();},0);
